import {ToolRegistry} from './registry.js';
import type {ToolExecutor} from './registry.js';
import {log, setLogger} from '../../shared/logger.js';

describe('ToolRegistry Input Validation (acceptance)', () => {
  const noop: ToolExecutor = async () => 'ok';

  it('validates input against schema and returns ToolResponse on failure', async () => {
    const registry = new ToolRegistry();
    let called = false;
    const executor: ToolExecutor = async () => {
      called = true;
      return 'ok';
    };

    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
          },
          required: ['location'],
        },
      },
      executor
    );

    // Call with missing required property
    const response = await registry.execute('test_tool', {});

    expect(response.result).toMatch(/location/);
    expect(called).toBe(false);
  });

  it('passes unlisted extra properties through to the executor', async () => {
    const registry = new ToolRegistry();
    let receivedInput: Record<string, unknown> = {};
    const executor: ToolExecutor = async input => {
      receivedInput = input;
      return 'ok';
    };

    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {
            known: {type: 'string'},
          },
        },
      },
      executor
    );

    const input = {known: 'value', unknown: 'extra'};
    await registry.execute('test_tool', input);

    // Should be exactly the same object, no extra properties removed, no defaults added
    expect(receivedInput).toEqual(input);
  });

  it('rejects wrong-typed fields with descriptive, redacted messages', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {
            age: {type: 'number'},
          },
        },
      },
      noop
    );

    const sensitiveValue = 'twenty-five';
    const response = await registry.execute('test_tool', {age: sensitiveValue});

    // Should name the field and the expected type
    expect(response.result).toMatch(/age/);
    expect(response.result).toMatch(/number/);
    // Should NOT contain the value
    expect(response.result).not.toContain(sensitiveValue);
  });

  it('throws at registration time for uncompilable schemas', () => {
    const registry = new ToolRegistry();
    const invalidSchema = {
      type: 'object',
      properties: {
        foo: {type: 'not-a-valid-type'},
      },
    };

    expect(() => {
      registry.register(
        {
          name: 'bad_tool',
          description: 'test',
          inputSchema: invalidSchema as any,
        },
        noop
      );
    }).toThrow(/bad_tool/);
  });

  it('resolves and validates dynamic schemas per call', async () => {
    const registry = new ToolRegistry();
    let schemaType = 'string';
    const definitionSource = () => ({
      name: 'dynamic_tool',
      description: 'test',
      inputSchema: {
        type: 'object',
        properties: {
          val: {type: schemaType},
        },
      },
    });

    registry.register(definitionSource, noop);

    // First call expects string
    const res1 = await registry.execute('dynamic_tool', {val: 123});
    expect(res1.result).toMatch(/string/);

    // Change schema to expect number
    schemaType = 'number';
    const res2 = await registry.execute('dynamic_tool', {val: 123});
    // Now it should pass (or at least not fail due to being a string)
    expect(res2.result).toBe('ok');
  });

  it('caches compiled schemas for static tool definitions', async () => {
    // We use a Proxy to observe accesses to the schema object.
    // Ajv compilation should happen once.
    const inputSchema = {
      type: 'object',
      properties: {val: {type: 'string'}},
    };

    let accessCount = 0;
    const proxySchema = new Proxy(inputSchema, {
      get(target, prop, receiver) {
        // Properties Ajv typically reads during compilation
        if (['type', 'properties', 'required', 'items'].includes(prop as string)) {
          accessCount++;
        }
        return Reflect.get(target, prop, receiver);
      },
    });

    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'cached_tool',
        description: 'test',
        inputSchema: proxySchema as any,
      },
      noop
    );

    const accessesAfterRegister = accessCount;
    expect(accessesAfterRegister).toBeGreaterThan(0);

    for (let i = 0; i < 10; i++) {
      await registry.execute('cached_tool', {val: 'ok'});
    }

    // Should not have re-accessed/re-compiled the schema during execution
    expect(accessCount).toBe(accessesAfterRegister);
  });

  it('does not leak sensitive input values in logs during validation failure', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'secure_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {
            password: {type: 'string', minLength: 10},
          },
        },
      },
      noop
    );

    const logs: any[] = [];
    const testLogger = {
      debug: (cat: string, msg: string, data: any) => logs.push({level: 'DEBUG', cat, msg, data}),
      info: (cat: string, msg: string, data: any) => logs.push({level: 'INFO', cat, msg, data}),
      warn: (cat: string, msg: string, data: any) => logs.push({level: 'WARN', cat, msg, data}),
      error: (cat: string, msg: string, data: any) => logs.push({level: 'ERROR', cat, msg, data}),
    };

    setLogger(testLogger);
    try {
      const sensitiveValue = 'SHORT_PWD';
      await registry.execute('secure_tool', {password: sensitiveValue});

      // Verify no log line contains the sensitive value
      for (const entry of logs) {
        const serialized = JSON.stringify(entry);
        expect(serialized).not.toContain(sensitiveValue);
      }
    } finally {
      setLogger(undefined); // Restore default logger
    }
  });

  it('still throws Unknown tool error for unregistered names', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('non_existent', {})).rejects.toThrow('Unknown tool: non_existent');
  });
});

import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('ChatOrchestrator tool loop validation recovery (acceptance)', () => {
  const promptBuilder = new PromptBuilder({identity: 'Test'});
  const SENT_AT = '2026-01-01T00:00:00.000Z';

  function createSession(content: string): ChatSession {
    return {
      sessionId: 's1',
      userId: 'u1',
      entries: [{role: 'user', content, timestamp: SENT_AT}],
    };
  }

  it('tool loop handles rejected call and corrected retry', async () => {
    const registry = new ToolRegistry();
    let executorCalledWith: any = null;

    registry.register(
      {
        name: 'weather',
        description: 'get weather',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
          },
          required: ['location'],
        },
      },
      async input => {
        executorCalledWith = input;
        return 'The weather is sunny';
      }
    );

    // Mock provider that first sends a bad call, then a good one
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        if (round === 0) {
          round++;
          // Bad call: missing location
          yield {
            type: 'tool_use',
            toolCall: {id: 'call-1', name: 'weather', input: {}},
          };
          yield {type: 'stop', stopReason: 'tool_use'};
        } else if (round === 1) {
          round++;
          // Verify we saw the error in the history
          const lastMessage = params.messages[params.messages.length - 1];
          // In the history, it should be a tool_result with the error message
          const toolResult = lastMessage.content.find((c: any) => c.type === 'tool_result' && c.toolCallId === 'call-1');

          if (toolResult && toolResult.content.includes('location')) {
            // Corrected call
            yield {
              type: 'tool_use',
              toolCall: {id: 'call-2', name: 'weather', input: {location: 'Berlin'}},
            };
            yield {type: 'stop', stopReason: 'tool_use'};
          } else {
            yield {type: 'text', text: 'Error: validation message not found in history'};
            yield {type: 'stop', stopReason: 'end_turn'};
          }
        } else {
          yield {type: 'text', text: 'All done!'};
          yield {type: 'stop', stopReason: 'end_turn'};
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const result = await orchestrator.processMessage(createSession('weather?'));

    expect(executorCalledWith).toEqual({location: 'Berlin'});
    expect(result).toContain('All done!');
  });
});

